import unittest

from geometry import CROSSWALK_RECT, TARGET_X, check as geometry_check
from runner import check as runner_check, control_for, survey, survey_crosswalk


class FakeCarla:
    class LaneType:
        Parking = 'parking'

    class Location:
        def __init__(self, x, y, z):
            self.x, self.y, self.z = x, y, z


class FakeWaypoint:
    def __init__(self, x, y, wrong=False):
        self.road_id, self.lane_id, self.lane_type = 1, -1 if wrong else -2, 'parking'
        self.transform = type('T', (), {'location': FakeCarla.Location(x, y, 8)})()


class FakeWorld:
    def __init__(self, wrong=False):
        self.wrong = wrong

    def get_map(self):
        return self

    def get_waypoint(self, location, project_to_road, lane_type):
        return FakeWaypoint(location.x, location.y, self.wrong)

    def get_crosswalks(self):
        if self.wrong:
            return []
        return [FakeCarla.Location(x, y, 8) for x, y in ((0,-6.5),(4,-6.5),(4,0),(0,0))]


class NativeDraft(unittest.TestCase):
    def test_geometry_and_camera_plan(self):
        self.assertEqual(geometry_check()['crosswalk_rect_xyxy_m'], CROSSWALK_RECT)
        self.assertEqual(TARGET_X, {'controlled_1': -14.0, 'controlled_2': -5.0,
                                    'boundary_20ft': -8.096, 'stop_near': -5.0,
                                    'stand_near': -5.0})
        self.assertEqual(runner_check()['frames'], 600)
        self.assertEqual(len(runner_check()['camera_names']), 4)
        self.assertFalse(runner_check()['physical_acceptance_claimed'])

    def test_distinct_action_control_policies(self):
        self.assertTrue(control_for('controlled_2', 250, 1, 0)['hand_brake'])
        self.assertFalse(control_for('stand_near', 250, 1, 0)['hand_brake'])
        self.assertEqual(control_for('stop_near', 301, 1, 0)['throttle'], .25)
        self.assertEqual(control_for('stop_near', 250, 1, 0)['brake'], 1.0)

    def test_parking_lane_survey_gate(self):
        self.assertEqual(len(survey(FakeWorld(), FakeCarla)), 5)
        self.assertEqual(len(survey_crosswalk(FakeWorld())), 4)
        with self.assertRaisesRegex(RuntimeError, 'readback failed'):
            survey(FakeWorld(wrong=True), FakeCarla)
        with self.assertRaisesRegex(RuntimeError, 'marked-crosswalk geometry'):
            survey_crosswalk(FakeWorld(wrong=True))
        shifted = FakeWorld()
        shifted.get_crosswalks = lambda: [FakeCarla.Location(x, y, 8)
                                            for x, y in ((1,-6.5),(5,-6.5),(5,0),(1,0))]
        with self.assertRaisesRegex(RuntimeError, 'crosswalk extent differs'):
            survey_crosswalk(shifted)

"""Join separately reviewed original sources without rewriting Native capture."""
import hashlib
import json
from pathlib import Path

FIELDS = (
    'jurisdiction_source_id', 'marked_crosswalk_source_id',
    'crosswalk_extent_source_id', 'responsible_person_source_id',
    'traffic_conflict_review_source_id', 'law_compliance_review_source_id',
    'directions_review_source_id',
)


def join(attempt, inventory):
    attempt = Path(attempt).resolve()
    review_path = attempt / 'crosswalk-source-review.json'
    if not review_path.is_file():
        raise ValueError('independent crosswalk source review missing')
    review = json.loads(review_path.read_text())
    if review.get('format') != 'c229397-crosswalk-source-review-v1':
        raise ValueError('crosswalk source review format differs')
    if review.get('assignment_id') != inventory.get('assignment_id'):
        raise ValueError('crosswalk source review assignment differs')
    findings = review.get('findings')
    if not isinstance(findings, dict) or set(findings) != set(FIELDS):
        raise ValueError('crosswalk source review findings incomplete')
    joined = dict(inventory)
    for field in FIELDS:
        finding = findings[field]
        if not isinstance(finding, dict) or finding.get('finding') not in ('present', 'absent', 'unresolved'):
            raise ValueError('crosswalk source review finding invalid: ' + field)
        rel = finding.get('source')
        if not isinstance(rel, str) or not rel or Path(rel).is_absolute() or '..' in Path(rel).parts:
            raise ValueError('crosswalk source review path invalid: ' + field)
        source = (attempt / rel).resolve()
        if not source.is_relative_to(attempt) or not source.is_file():
            raise ValueError('crosswalk source review file missing: ' + field)
        digest = hashlib.sha256(source.read_bytes()).hexdigest()
        if digest != finding.get('sha256'):
            raise ValueError('crosswalk source review hash differs: ' + field)
        if field == 'marked_crosswalk_source_id' and finding['finding'] != 'present':
            raise ValueError('marked crosswalk has not been established')
        joined[field] = rel + '#sha256=' + digest + '#finding=' + finding['finding']
    return joined, hashlib.sha256(review_path.read_bytes()).hexdigest(), {
        field: findings[field]['finding'] for field in FIELDS}

